guided_steps.solution:
# for文を使って1から10を表示
for i in range(1, 11):
    print(i)

# 九九表を作成
for i in range(1, 10):
    for j in range(1, 10):
        result = i * j
        print(str(i) + " x " + str(j) + " = " + str(result))

